pub fn medians(xs: List[Int], k: Int) -> List[Float] {
  var out: List[Float] = []
  let n = xs.len()
  if k < 1 or k > n {
    return out
  }
  for i in range(0, n - k + 1) {
    let ordered = xs.slice(i, i + k).sort()
    let mid = k / 2
    if k % 2 == 1 {
      out = out.push(ordered.get_or(mid, 0).to_float())
    } else {
      let total = ordered.get_or(mid - 1, 0) + ordered.get_or(mid, 0)
      out = out.push(total.to_float() / 2.0)
    }
  }
  return out
}
